const adminPaymentSessionPaymentID = `-- name: AdminPaymentSessionPaymentID :one
SELECT payment_id FROM payment_sessions WHERE id = $1
`

func (q *Queries) AdminPaymentSessionPaymentID(ctx context.Context, id string) (string, error) {
	row := q.db.QueryRow(ctx, adminPaymentSessionPaymentID, id)
	var payment_id string
	err := row.Scan(&payment_id)
	return payment_id, err
}

const adminRecentLogs = `-- name: AdminRecentLogs :many
SELECT l.id, l.app_id, l.message, l.level, l.created_at, a.name AS app_name
FROM logs l
LEFT JOIN apps a ON a.id = l.app_id
ORDER BY l.created_at DESC, l.id DESC
LIMIT 10
`

